smooth_3x3._internal = {
    point_pos        = point_pos,
    rot_perm         = rot_perm,
    rotated          = rotated,
    shape_names      = shape_names,
    shape_index      = shape_index,
    raw_shapes       = raw_shapes,
    pinned_points    = pinned_points,
    corner_factors   = corner_factors,
    center_pairs     = center_pairs,
    node_offsets     = node_offsets,
    edge_cycle       = edge_cycle,
    generate_ring_candidates    = generate_ring_candidates,
    generate_center_candidates  = generate_center_candidates,
}
setmetatable(smooth_3x3, {__call = function(_, ...) return smooth_impl(...) end})
return smooth_3x3
]]

return smooth_impl
